head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

//채권분류코드
scwin.vScrenID = "ULDINS90500.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};


/********************************************** 
 * 함수명   : ins_search
 * 설명       : 채권분류코드 조회 한다.
 ***********************************************/
scwin.ins_search = function(bndClssCd) {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS90500_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.common.select.listBndClassCdInquiry" + "&{P}BND_CLSS_CD=" + bndClssCd;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    var CD3 = dts_List.getCellData(row, "CD3");
    var BND_TP_NM = dts_List.getCellData(row, "BND_TP_NM");
    $c.frame.path("../").ins_popupRtn_cdnm(CD3, BND_TP_NM);
    await $c.frame.CloseFrame();
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_jongmok_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.gform_onload = function() {
    var arrPar = new Array();
    var parentWin = $c.frame.path("../");
    var fn_GetPar = parentWin.fn_GetParam;
    if (fn_GetPar != undefined) {
        fn_GetPar(arrPar);
        test.setValue(((arrPar.length >= 1) && (arrPar[0] != undefined) ? arrPar[0] : ""));
    }

    //alert(test);
    scwin.ins_search(test); // 예제임 수정 필요하다 .

};
